+     */
+    @Override
+    public void act(List<Entity> newAnimals, Weather weather, TimeOfDay time) {
+        incrementAge();
+        incrementHunger();
+
+        if (!isAlive()) {
+            return;
+        }
+
+        giveBirth(newAnimals);
+
+        if (time == restingTime()) {
+            return;
